// Adapted from s-soltys/LipSync (Unlicense). Benchmark-only LPC/NN runtime.
import fs from 'node:fs/promises';
const INPUT_RATE=24000, RATE=44100, WINDOW=794, STEP=882, STRIDE=7, ENERGY_THRESHOLD=0.025;
const ID_TO_VISEME=new Map([[0,'sil'],[2,'aa'],[3,'aa'],[6,'I'],[7,'I'],[10,'U'],[11,'U'],[14,'O'],[15,'O'],[20,'RR'],[21,'RR'],[30,'SS'],[31,'SS'],[40,'CH'],[41,'CH'],[52,'DD'],[53,'DD'],[62,'FF'],[63,'FF']]);
export const SUPPORTED_VISEMES=Object.freeze(['aa','I','U','O','RR','SS','CH','DD','FF','sil']);
function resample(input){const n=Math.floor(input.length*RATE/INPUT_RATE), out=new Float32Array(n); for(let i=0;i<n;i++){const x=i*INPUT_RATE/RATE,j=Math.floor(x),f=x-j;out[i]=(input[j]||0)*(1-f)+(input[Math.min(j+1,input.length-1)]||0)*f;}return out;}
function analyze(x){const p=9,L=x.length,dl=new Array(L).fill(0),R=new Array(p+1).fill(0);let r1=0,r2=0;for(let k=0;k<L;k++){R[0]+=x[k]*x[k];dl[k]=r1;r1=x[k];r2=dl[k];}for(let i=1;i<=p;i++){r1=0;r2=0;for(let k=0;k<L;k++){R[i]+=dl[k]*x[k];const old=dl[k];dl[k]=r1;r1=old;r2=dl[k];}}if(Math.abs(R[0])<1e-15)return new Array(p).fill(0);const K=new Array(p).fill(0),A=new Array(p+1).fill(0),Am=new Array(p+1).fill(0);A[0]=Am[0]=1;let E=R[0];for(let m=1;m<=p;m++){let err=0;for(let k=1;k<m;k++)err+=Am[k]*R[m-k];const km=(R[m]-err)/E;K[m-1]=-km;A[m]=km;for(let k=1;k<m;k++)A[k]=Am[k]-km*Am[m-k];E=(1-km*km)*E;for(let k=0;k<=p;k++)Am[k]=A[k];if(Math.abs(E)<1e-15)break;}return K;}
function runNetwork(layers,input){let values=input;for(const layer of layers){values=layer.map(n=>{let z=n.bias??NaN;for(let i=0;i<n.weights.length;i++)z+=(n.weights[i]??NaN)*values[i];return 1/(1+Math.exp(-z));});}return values;}
function decode(output){if(!output.length||Number.isNaN(output[0]))return 'sil';let id=0;for(const value of output)id=id*2+(value>=0.5?1:0);return ID_TO_VISEME.get(id)||'sil';}
export async function classifyPcm24k(pcmPath,weightsPath){const [raw,modelRaw]=await Promise.all([fs.readFile(pcmPath),fs.readFile(weightsPath,'utf8')]);const pcm=new Float32Array(raw.length/2);for(let i=0;i<pcm.length;i++)pcm[i]=raw.readInt16LE(i*2)/32768;const model=JSON.parse(modelRaw.replace(/\bNaN\b/g,'null'));for(const vector of model.test_vectors||[]){const actual=runNetwork(model.layers,vector.input);if(actual.some((value,i)=>Math.abs(value-vector.expected_output[i])>1e-9))throw new Error('Vendored s-soltys/LipSync NN failed its upstream reference vectors');}const audio=resample(pcm),events=[];for(let pos=STEP;pos<audio.length;pos+=STEP){const end=Math.min(pos+WINDOW,audio.length),samples=[];let energy=0;for(let i=pos;i<end;i+=STRIDE){samples.push(audio[i]);energy+=Math.abs(audio[i]);}energy=samples.length?energy/samples.length:0;const name=energy<ENERGY_THRESHOLD?'sil':decode(runNetwork(model.layers,analyze(samples)));events.push({sourceTimeMs:Number((pos/RATE*1000).toFixed(1)),name,energy});}for(let i=1;i<events.length-1;i++){if(events[i].name!==events[i-1].name&&events[i].name!==events[i+1].name)events[i].name=events[i+1].name!=='sil'?events[i+1].name:events[i-1].name;}return events;}
